const tabId = 1148881640;
const res = await browserjs(tabId, () => {
  // Let's find all text or elements that have prices like $...
  const allElements = Array.from(document.querySelectorAll('*'));
  const priceElements = allElements.filter(el => {
    // Only elements with direct text containing $
    return Array.from(el.childNodes).some(n => n.nodeType === Node.TEXT_NODE && /\$\d+/.test(n.textContent));
  });

  return priceElements.map(el => {
    // find container
    let p = el;
    while (p && p.parentElement && p.parentElement.tagName !== 'BODY' && p.parentElement.innerText.length < 500) {
      p = p.parentElement;
    }
    return p.innerText;
  }).filter((v, i, a) => a.indexOf(v) === i);
});
console.log("Price blocks count:", res.length);
console.log("Price blocks:", JSON.stringify(res.slice(0, 10), null, 2));

const tabId = 1148881640;
const detailedProducts = await browserjs(tabId, () => {
  // Find all cards
  // In Google Shopping results, cards often have anchor tags or distinct container elements
  const cards = [];

  // Look for product containers
  // Let's find elements that contain both a price ($xx.xx or $xx) and a discount / sale indicator or retailer
  const elements = Array.from(document.querySelectorAll('div, article, li'));

  // Filter to find the tightest containers that have product info
  const productContainers = elements.filter(el => {
    const text = el.innerText || "";
    // Has price between $25 and $60
    const hasPrice = /\$\d+(\.\d+)?/.test(text);
    const hasDiscount = /OFF|Usually|Sale|LOW PRICE|\$\d+.*?\$\d+/i.test(text);
    const isProduct = /coffee/i.test(text);
    const isLeafCard = el.querySelectorAll('div, article, li').length < 25 && el.querySelectorAll('div, article, li').length > 3;
    return hasPrice && hasDiscount && isProduct && isLeafCard;
  });

  // Deduplicate nested containers by keeping those that don't contain other matching containers
  const leafCards = productContainers.filter(c => {
    return !productContainers.some(other => other !== c && c.contains(other));
  });

  return leafCards.map(card => {
    const lines = card.innerText.split('\n').map(l => l.trim()).filter(Boolean);
    const link = card.querySelector('a')?.href || "";
    return {
      text: lines.join(' | '),
      lines,
      link
    };
  });
});

console.log("Found leaf cards count:", detailedProducts.length);
console.log(JSON.stringify(detailedProducts, null, 2));

