  tabId,
  method: "DOMSnapshot.captureSnapshot",
  params: { computedStyles: [] }
});

// Look for layout bounds in documents
for (let d = 0; d < res.documents.length; d++) {
  const doc = res.documents[d];
  const strings = res.strings;
  const layout = doc.layout;
  if (!layout) continue;

  // check if any layout node corresponds to tile
  for (let i = 0; i < layout.nodeIndex.length; i++) {
    const nodeIdx = layout.nodeIndex[i];
    const nodeNameIdx = doc.nodes.nodeName[nodeIdx];
    const nodeName = strings[nodeNameIdx];
    // check attributes
    const attrIdxs = doc.nodes.attributes ? doc.nodes.attributes[nodeIdx] : [];
    let isTile = false;
    let className = "";
    if (attrIdxs) {
      for (let a = 0; a < attrIdxs.length; a += 2) {
        if (strings[attrIdxs[a]] === 'class') {
          className = strings[attrIdxs[a+1]];
          if (className.includes('rc-imageselect-tile')) {
            isTile = true;
          }
        }
      }
    }
    if (isTile) {
      console.log(`Doc ${d}, node ${nodeIdx}, class: ${className}, bounds:`, layout.bounds[i]);
    }
  }
}

