  tabId,
  method: "DOMSnapshot.captureSnapshot",
  params: { computedStyles: [] }
});

// Find table or grid in bframe
for (let d = 0; d < res.documents.length; d++) {
  const doc = res.documents[d];
  const strings = res.strings;
  const layout = doc.layout;
  if (!layout) continue;

  for (let i = 0; i < (layout.nodeIndex || []).length; i++) {
    const nodeIdx = layout.nodeIndex[i];
    const attrIdxs = doc.nodes.attributes ? doc.nodes.attributes[nodeIdx] : null;
    if (attrIdxs) {
      for (let a = 0; a < attrIdxs.length; a += 2) {
        if (strings[attrIdxs[a]] === 'class' && strings[attrIdxs[a+1]] && strings[attrIdxs[a+1]].includes('rc-imageselect-table-44')) {
          console.log(`Found 4x4 table in doc ${d}: bounds =`, layout.bounds[i]);
        }
      }
    }
  }
}

