const tabId = 1148881640;
const products = await browserjs(tabId, () => {
  // Let's inspect the product containers or headings
  // Often on Google Shopping udm=28, products are inside certain divs or have headings/prices
  const results = [];

  // Method 1: Look for elements with data attributes or product card structure
  // Let's inspect all text blocks that contain '$'
  const items = Array.from(document.querySelectorAll('div[data-docid], div[data-sh-pr]'));

  // Method 2: Look at standard shopping result elements
  const allH3 = Array.from(document.querySelectorAll('h3')).map(h => {
    // Find parent container
    let parent = h.parentElement;
    for (let i = 0; i < 5; i++) {
      if (parent && (parent.innerText.includes('$') || parent.textContent.includes('$'))) {
        break;
      }
      if (parent) parent = parent.parentElement;
    }
    return {
      title: h.textContent?.trim(),
      details: parent ? parent.innerText : ""
    };
  });

  return {
    h3Count: allH3.length,
    h3Samples: allH3.slice(0, 10)
  };
});
console.log(JSON.stringify(products, null, 2));

