const tabId = 1148881640;
const res = await browserjs(tabId, () => {
  // Let's find all text or elements that have prices like $...
  const allElements = Array.from(document.querySelectorAll('*'));
  const priceElements = allElements.filter(el => {
    // Only elements with direct text containing $
    return Array.from(el.childNodes).some(n => n.nodeType === Node.TEXT_NODE && /\$\d+/.test(n.textContent));
  });

  return priceElements.map(el => {
    // find container
    let p = el;
    while (p && p.parentElement && p.parentElement.tagName !== 'BODY' && p.parentElement.innerText.length < 500) {
      p = p.parentElement;
    }
    return p.innerText;
  }).filter((v, i, a) => a.indexOf(v) === i);
});
console.log("Price blocks count:", res.length);
console.log("Price blocks:", JSON.stringify(res.slice(0, 10), null, 2));

